<script setup lang="ts">
import {ref,computed} from 'vue';import Panel from '../components/Panel.vue';import {api,run,refresh,current,health,events,busy,notify} from '../store'
const question=ref('');const answer=ref<any>(null);const history=computed(()=>events.value.filter(e=>e.action==='culture_answer'&&e.seal_id===(current.value?.id||null)));const last=computed(()=>answer.value||history.value[0]?.details)
async function ask(){await run(async()=>{if(!question.value.trim())return;answer.value=await api('/chat',{method:'POST',body:JSON.stringify({question:question.value,seal_id:current.value?.id||null})});await refresh();notify('真实模型回答已存档，请核验引用来源。')})}
const suggestions=['如何区分朱文与白文？','怎样生成可打印STL？','实际盖印前需要检查什么？']
</script>
<template><div class="assistant-grid"><Panel title="印文化AI智能助手" note="连接业务印谱资料和文化知识库"><div class="assistant-status"><span :class="['pill',health?.ai.culture.configured?'green':'']">{{health?.ai.culture.configured?'模型已配置 · 待调用验证':'大模型未配置 · 暂不可用'}}</span><span class="pill">引用来源 · 人工核验</span></div><div class="conversation"><template v-if="last"><div class="chat-user">{{last.question}}</div><div class="chat-answer"><h3>古印修复与制印建议</h3><p>{{last.answer}}</p><small>模型 {{last.model}} · 真实推理已归档</small><ul><li v-for="(r,i) in last.references" :key="r.id"><a v-if="r.url" :href="r.url" target="_blank" rel="noopener">[{{Number(i)+1}}] {{r.title}}</a><span v-else>[{{Number(i)+1}}] {{r.title}}</span></li></ul></div></template><div v-else class="chat-answer"><h3>古印修复与制印助手</h3><p>可围绕印文形制、朱白文、镜像与实体制造提出问题。回答仅在真实大模型调用成功后显示，并保留知识来源与处理记录。</p><p>目前尚未配置可用模型，界面不会显示虚构的AI回答。已提供服务端接入与数据库知识检索接口。</p><small>需要配置可用的模型服务后，才能生成真实回答。</small></div></div><div class="chips"><button v-for="s in suggestions" :key="s" class="chip" @click="question=s">{{s}}</button></div><form class="chat-input" @submit.prevent="ask"><input v-model="question" placeholder="请输入您的古印文化或印面制造问题……" aria-label="文化助手提问" maxlength="2000"><button class="primary" :disabled="busy||!question.trim()">发送 ↗</button></form></Panel><Panel title="当前关联印谱" note="从问题到可溯源的辅助解释"><div class="assistant-image"><img :src="current?.original_url||'/assets/restored.png'" alt="当前关联印谱或设计参考"></div><dl class="data-list"><div><dt>印谱名称</dt><dd>{{current?.title||'尚未选择'}}</dd></div><div><dt>分析方式</dt><dd>知识检索 + 大模型</dd></div><div><dt>历史归属</dt><dd>待文献核验</dd></div><div><dt>回答策略</dt><dd>依据证据生成</dd></div></dl><div class="notice"><h4>专家校订机制</h4><p>印文释读、作者、断代与历史背景均应对应文献来源，避免未经证实的自动判定。</p></div></Panel></div></template>
